<h2>Оформление заказа</h2><p>Сумма товаров: <?= number_format($cart['total'],2,',',' ') ?> ₽</p><form method="post" action="/checkout"><input type="hidden" name="csrf" value="<?= e($_SESSION['csrf']) ?>"><?php foreach (['name'=>'Имя','email'=>'Email','address'=>'Адрес для курьера'] as $key=>$label): ?><label><?= e($label) ?> <input name="<?= e($key) ?>" value="<?= e($values[$key] ?? '') ?>"> <span class="error"><?= e($errors[$key] ?? '') ?></span></label><?php endforeach; ?><label>Доставка <select name="delivery"><option value="">Выберите доставку</option><?php foreach ($methods as $method): ?><option value="<?= e($method['id']) ?>" <?= ($values['delivery'] ?? '') === $method['id'] ? 'selected' : '' ?>><?= e($method['title']) ?> — <?= e($method['price']) ?> ₽</option><?php endforeach; ?></select> <span class="error"><?= e($errors['delivery'] ?? '') ?></span></label><?php foreach (['cart','csrf'] as $key): ?><p class="error"><?= e($errors[$key] ?? '') ?></p><?php endforeach; ?><button>Оформить</button></form>
